corrected_code:
router.patch('/workspaces/:workspaceId/members/:memberId/role', koaJwtCheck, async (ctx) => {
  const { workspaceId, memberId } = ctx.params;
  const { newRole } = ctx.request.body;

  const callerRole = await drizzle.select()
    .from(workspaceMembers)
    .where(and(
      eq(workspaceMembers.workspaceId, workspaceId),
      eq(workspaceMembers.userId, ctx.state.user.id),
      eq(workspaceMembers.role, 'WORKSPACE_OWNER')
    ));
  if (!callerRole.length) {
    ctx.status = 403;
    ctx.body = { error: 'Forbidden: only workspace owners can change member roles' };
    return;
  }

  const updated = await drizzle.update(workspaceMembers)
    .set({ role: newRole })
    .where(and(
      eq(workspaceMembers.workspaceId, workspaceId),
      eq(workspaceMembers.userId, memberId)
    ))
    .returning();

  if (!updated.length) {
    ctx.status = 404;
    ctx.body = { error: 'Workspace member record not found' };
    return;
  }
  ctx.body = { updatedMember: updated[0] };
});
